mapper.select:
SELECT d.id AS definitionId, d.flow_code AS flowCode, d.flow_name AS flowName, d.category, d.version, d.is_publish AS publishStatus, d.activity_status AS activityStatus, d.form_custom AS formCustom, d.form_path AS formPath, d.ext, d.update_time AS updateTime FROM flow_definition d WHERE d.del_flag = '0' AND d.tenant_id = #{tenantId} AND (
d.id = #{k.value}
d.flow_code = #{k.value}
)

SELECT n.definition_id AS definitionId, n.node_code AS nodeCode, n.node_name AS nodeName, n.node_type AS nodeType, n.coordinate, n.handler_path AS handlerPath, n.permission_flag AS permissionFlag FROM flow_node n WHERE n.del_flag = '0' AND n.tenant_id = #{tenantId} AND n.definition_id IN
#{id}
ORDER BY n.definition_id, n.node_code

SELECT s.definition_id AS definitionId, s.now_node_code AS fromNodeCode, s.next_node_code AS toNodeCode, s.skip_name AS label, s.skip_condition AS condition, s.skip_type AS skipType FROM flow_skip s WHERE s.del_flag = '0' AND s.tenant_id = #{tenantId} AND s.definition_id IN
#{id}
ORDER BY s.definition_id, s.now_node_code, s.next_node_code

SELECT *
FROM flow_instance
WHERE del_flag = '0'
AND tenant_id = #{tenantId}
AND flow_code = #{flowCode}
AND business_id = #{businessId}
LIMIT 1

SELECT * FROM flow_instance WHERE del_flag = '0' AND tenant_id = #{tenantId} AND (
(flow_code = #{k.flowCode} AND business_id = #{k.businessId})
)

SELECT *
FROM flow_idempotency
WHERE del_flag = '0'
AND tenant_id = #{tenantId}
AND idempotency_key = #{idempotencyKey}
LIMIT 1

mapper.update:
UPDATE flow_idempotency
SET status = 'SUCCESS', response_json = #{responseJson}, update_time = now()
WHERE tenant_id = #{tenantId} AND idempotency_key = #{idempotencyKey}

UPDATE flow_idempotency
SET status = 'FAILED', error_code = #{errorCode}, error_message = #{errorMessage}, update_time = now()
WHERE tenant_id = #{tenantId} AND idempotency_key = #{idempotencyKey}

mapper.select:
SELECT t.id AS taskId, t.instance_id AS instanceId, t.definition_id AS definitionId, t.node_code AS nodeCode, t.node_name AS nodeName, t.flow_status AS flowStatus, t.create_time AS createTime, t.update_time AS updateTime, t.revision, i.flow_code AS flowCode, i.business_id AS businessId, i.business_title AS businessTitle, i.starter_id AS starterId, i.starter_name AS starterName FROM flow_task t INNER JOIN flow_user fu ON fu.associated = t.id AND fu.type = '1' AND fu.del_flag = '0' INNER JOIN flow_instance i ON i.id = t.instance_id AND i.del_flag = '0' WHERE t.del_flag = '0' AND t.tenant_id = #{tenantId} AND t.flow_status = '1' AND t.node_type = 1 AND fu.processed_by = #{assigneeId}
AND (t.node_name LIKE concat('%', #{keyword}, '%') OR i.business_id LIKE concat('%', #{keyword}, '%'))
AND i.flow_code = #{flowCode}
AND (t.create_time < #{cursorTime} OR (t.create_time = #{cursorTime} AND t.id < #{cursorId}))
ORDER BY t.create_time DESC, t.id DESC LIMIT #{limit}

SELECT COUNT(*) FROM flow_task t INNER JOIN flow_user fu ON fu.associated = t.id AND fu.type = '1' AND fu.del_flag = '0' INNER JOIN flow_instance i ON i.id = t.instance_id AND i.del_flag = '0' WHERE t.del_flag = '0' AND t.tenant_id = #{tenantId} AND t.flow_status = '1' AND t.node_type = 1 AND fu.processed_by = #{assigneeId}
AND (t.node_name LIKE concat('%', #{keyword}, '%') OR i.business_id LIKE concat('%', #{keyword}, '%'))
AND i.flow_code = #{flowCode}

SELECT t.id AS taskId, t.instance_id AS instanceId, t.definition_id AS definitionId, t.node_code AS nodeCode, t.node_name AS nodeName, t.flow_status AS flowStatus, t.create_time AS createTime, t.update_time AS updateTime, t.revision, i.flow_code AS flowCode, i.business_id AS businessId, i.business_title AS businessTitle, i.starter_id AS starterId, i.starter_name AS starterName FROM flow_task t INNER JOIN flow_instance i ON i.id = t.instance_id AND i.del_flag = '0' WHERE t.del_flag = '0' AND t.tenant_id = #{tenantId} AND t.id IN
#{id}
AND EXISTS ( SELECT 1 FROM flow_user fu WHERE fu.associated = t.id AND fu.type = '1' AND fu.del_flag = '0' AND fu.processed_by = #{assigneeId} )

SELECT * FROM ( SELECT h.id AS historyId, h.instance_id AS instanceId, h.node_code AS nodeCode, h.node_name AS nodeName, h.approver_id AS handlerId, h.approver_name AS handlerName, h.skip_type AS skipType, h.cooperate_type AS cooperateType, h.message AS comment, h.create_time AS createTime, h.update_time AS updateTime, ROW_NUMBER() OVER (PARTITION BY h.instance_id ORDER BY h.update_time DESC, h.id DESC) AS rn FROM flow_his_task h WHERE h.del_flag = '0' AND h.tenant_id = #{tenantId} AND h.instance_id IN
#{id}
) t WHERE t.rn <= #{limitPerInstance} ORDER BY t.instanceId, t.updateTime DESC

SELECT * FROM ( SELECT i.id AS instanceId, i.flow_code AS flowCode, i.business_id AS businessId, i.flow_status AS flowStatus, h.approver_id AS handlerId, h.approver_name AS handlerName, h.skip_type AS skipType, h.cooperate_type AS cooperateType, h.message AS comment, h.update_time AS updateTime, ROW_NUMBER() OVER (PARTITION BY i.id ORDER BY h.update_time DESC, h.id DESC) AS rn FROM flow_instance i INNER JOIN flow_his_task h ON h.instance_id = i.id AND h.del_flag = '0' WHERE i.del_flag = '0' AND i.tenant_id = #{tenantId} AND (
(i.flow_code = #{k.flowCode} AND i.business_id = #{k.businessId})
) ) t WHERE t.rn = 1

SELECT COUNT(*)
FROM flow_user
WHERE del_flag = '0'
AND tenant_id = #{tenantId}
AND associated = #{taskId}
AND type = '1'
AND processed_by = #{operatorId}

mapper.update:
UPDATE flow_task
SET flow_status = #{flowStatus}, revision = revision + 1, update_time = now()
WHERE del_flag = '0'
AND tenant_id = #{tenantId}
AND id = #{taskId}
AND flow_status = '1'

    AND revision = #{expectedRevision}

UPDATE flow_instance
SET node_code = #{nodeCode}, node_name = #{nodeName}, flow_status = #{flowStatus},
    revision = revision + 1, update_time = now()
WHERE del_flag = '0'
AND tenant_id = #{tenantId}
AND id = #{instanceId}
AND flow_status = '1'

    AND revision = #{expectedRevision}
